import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"28、【大过】 巽下兑上","description":"周易口诀义 - 28、【大过】 巽下兑上","frontmatter":{"title":"28、【大过】 巽下兑上","description":"周易口诀义 - 28、【大过】 巽下兑上"},"headers":[],"relativePath":"zh/classics/koujueyi/030.md","filePath":"zh/classics/koujueyi/030.md"}'),r={name:"zh/classics/koujueyi/030.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_28、【大过】-巽下兑上" tabindex="-1">28、【大过】 巽下兑上 <a class="header-anchor" href="#_28、【大过】-巽下兑上" aria-label="Permalink to “28、【大过】 巽下兑上”">​</a></h1><p>彖曰：大过，大者过也。栋桡，本末弱也。刚过而中，巽而说行，「利有攸往」，乃亨。大过之时大矣哉！</p><p>象曰：泽灭木，大过。君子以独立不惧，遁世无闷。</p><p>初六：藉用白茅，无咎。</p><p>象曰：「藉用白茅」，柔在下也。</p><p>九二：枯杨生稊，老夫得其女妻，无不利。</p><p>象曰：老夫女妻，过以相与也。</p><p>九三：栋桡，凶。</p><p>象曰：「栋桡」之凶，不可以有辅也。</p><p>九四，栋隆，吉。有它，吝。</p><p>象曰：「栋隆」之「吉」，不挠乎下也。</p><p>九五，枯杨生华，老妇得其士夫，无咎无誉。</p><p>象曰：「枯杨生华」，何可久也！老妇士夫，亦可丑也。</p><p>上六，过涉灭顶，凶，无咎。</p><p>象曰：「过涉」之凶，不可咎也。</p><p>解读</p><p>「大过」者，谓过越也。衰乱之世，德大之人，过越常分，以拯患难，故曰「大过」也。「栋桡」者，栋谓屋栋也；桡，弱也，曲也。衰乱之世，始终皆弱也。「利有攸往，亨」者，谓德大之人，挺身救难，维持叔世，往必亨通。象曰「泽灭木，大过」者，「灭」，没也；「泽」，水也，如水泛溢以至没木，亦如小人过越常分也。「君子以独立不惧，遁世无闷」者，此论国之大柄，故先儒于此不敢梗槩而言也。谓君子欲有救难之心，卓尔独立，无所忧惧，不然，逃遁避世而心无忧闷也。</p><p>「初六，藉用白茅，无咎」者，以柔处下，苟能恭肃不怠，而用洁白之茅置羞于地，谨慎如此，虽遇大过之难而亦「无咎」也。</p><p>「九二：枯杨生稊，老夫得其女妻，无不利」者，以阳处阴，是拯难之人，又无偏应而无私党，犹如枯槁之杨，更生稊穗，所益久也。衰老之夫，得其少妻，可有后嗣也。救难既多，所济弘广，故无所不利也。</p><p>「九三：栋桡，凶」者，以阳处阳，不能拯救危难，又应于上，有偏系之心，故栋折榱崩而致凶也。</p><p>「九四：栋隆，吉，有它吝」者，以阳处阴，犹有救难之心，故栋得隆起也；独应于初，心不弘广，救难褊狭，故「有它吝」。</p><p>「九五：枯杨生华，老妇得其士夫，无咎，无誉」者，以阳居阳，不能拯救衰难，以其居尊，未即桡弱，犹如枯槁之杨，虽复生华，寻见衰落，亦犹衰老之妇而得少壮之夫，即不能有益也。以其处得尊位，才得免咎而己。既不能拯捄于人，故无声誉之美，故曰「无咎无誉」也。</p><p>上六：过涉灭顶，凶，无咎者，处「大过」之极，是救难过甚，遂「灭顶」也。为救时之苦，身至丧亡，深可哀而嗟之，又何有咎也！</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
